 IF (SELECT count(*) FROM public.competition_seasons WHERE id IN('62ce7ec9-459e-4acf-bec5-c6734a3199ef','be008d39-f175-45c1-a232-2148d84b1cf9') AND lifecycle='active' AND publication_state='published')<>2 THEN RAISE EXCEPTION 'Active editions changed'; END IF;
