CREATE TEMP TABLE protected_roster_rows ON COMMIT DROP AS
 SELECT 'fixtures' kind,to_jsonb(f) data FROM public.fixtures f WHERE EXISTS(SELECT 1 FROM public.result_versions r WHERE r.fixture_id=f.id) OR f.competition_season_id NOT IN('62ce7ec9-459e-4acf-bec5-c6734a3199ef','be008d39-f175-45c1-a232-2148d84b1cf9')
 UNION ALL SELECT 'results',to_jsonb(r) FROM public.result_versions r
 UNION ALL SELECT 'adjustments',to_jsonb(a) FROM public.standing_adjustments a
 UNION ALL SELECT 'audit',to_jsonb(a) FROM public.admin_audit_log a
 UNION ALL SELECT 'notes',to_jsonb(n) FROM public.team_fixture_notes n
 UNION ALL SELECT 'preferences',to_jsonb(v) FROM public.team_kickoff_preferences v WHERE team_id<>'bd834936-1b8a-4dd7-9013-d4b792862b67';
INSERT INTO public.teams(id,competition_season_id,legacy_id,name,status,standings_eligible,kit_colour)
 SELECT id,competition_season_id,legacy_id,name,status,standings_eligible,kit_colour FROM jsonb_populate_recordset(NULL::public.teams,$nt$[{"id":"38580a95-ab89-5ddd-a71d-c31ed05de4bd","competition_season_id":"62ce7ec9-459e-4acf-bec5-c6734a3199ef","legacy_id":"mon-black-magic","name":"Black Magic","status":"active","standings_eligible":true,"kit_colour":null,"profile_version":1},{"id":"435af587-f6ea-5030-a097-94ad466481c2","competition_season_id":"be008d39-f175-45c1-a232-2148d84b1cf9","legacy_id":"wed-xaywan","name":"Xaywan","status":"active","standings_eligible":true,"kit_colour":null,"profile_version":1}]$nt$::jsonb);
UPDATE public.teams SET status='active',standings_eligible=true,profile_version=profile_version+1 WHERE id='3a9c1f75-ecbe-4c05-85b9-bacfd65fb7ff';
UPDATE public.teams SET status='withdrawn',standings_eligible=false,profile_version=profile_version+1 WHERE id='9d563647-382e-405b-a34d-5912e8b34791';
UPDATE public.teams SET profile_version=profile_version+1 WHERE id='bd834936-1b8a-4dd7-9013-d4b792862b67';
DELETE FROM public.team_kickoff_preferences WHERE team_id='bd834936-1b8a-4dd7-9013-d4b792862b67';
INSERT INTO public.team_kickoff_preferences(team_id,kickoff_time,classification) VALUES ('bd834936-1b8a-4dd7-9013-d4b792862b67','19:00','required'),('bd834936-1b8a-4dd7-9013-d4b792862b67','19:40','required');
CREATE TEMP TABLE changed_fixture_ids ON COMMIT DROP AS SELECT f.id FROM public.fixtures f JOIN roster_plan p ON p.id=f.id WHERE ROW(f.round_number,f.match_date,f.kickoff_time,f.court,f.home_team_id,f.away_team_id,f.publication_state,f.schedule_status) IS DISTINCT FROM ROW(p.round_number,p.match_date,p.kickoff_time,p.court,p.home_team_id,p.away_team_id,p.publication_state,p.schedule_status);
DO $$ BEGIN IF EXISTS(SELECT 1 FROM changed_fixture_ids c JOIN public.result_versions r ON r.fixture_id=c.id) THEN RAISE EXCEPTION 'Cannot alter a fixture with recorded results'; END IF; END $$;
-- Free affected published slots inside the same transaction; readers see the old or complete new plan.
UPDATE public.fixtures SET publication_state='draft' WHERE id IN(SELECT id FROM changed_fixture_ids);
UPDATE public.fixtures f SET round_number=p.round_number,round_label=p.round_label,match_date=p.match_date,kickoff_time=p.kickoff_time,court=p.court,home_team_id=p.home_team_id,away_team_id=p.away_team_id,publication_state='published',schedule_status='scheduled',public_note=p.public_note FROM roster_plan p WHERE f.id=p.id AND f.id IN(SELECT id FROM changed_fixture_ids);
INSERT INTO public.fixtures(id,competition_season_id,legacy_id,round_number,round_label,match_date,kickoff_time,court,home_team_id,away_team_id,stage,publication_state,public_note,schedule_status)
 SELECT p.id,p.competition_season_id,p.legacy_id,p.round_number,p.round_label,p.match_date,p.kickoff_time,p.court,p.home_team_id,p.away_team_id,p.stage,p.publication_state,p.public_note,p.schedule_status FROM roster_plan p WHERE NOT EXISTS(SELECT 1 FROM public.fixtures f WHERE f.id=p.id);
INSERT INTO public.result_versions(fixture_id,revision,status,home_score,away_score,forfeit_side,published_at)
 SELECT fixture_id,1,'published',home_score,away_score,forfeit_side,now() FROM jsonb_to_recordset($scores$[{"fixture_id":"5d6361e4-87b0-50b7-9cf4-a62d8915aa98","home_score":3,"away_score":3,"forfeit_side":null},{"fixture_id":"d1e37fa1-c7e6-4763-894d-40430a0671dd","home_score":3,"away_score":3,"forfeit_side":null},{"fixture_id":"7fada165-ea84-454b-b235-ba08a243e02b","home_score":0,"away_score":5,"forfeit_side":"home"},{"fixture_id":"19db805f-e697-4b6b-91c8-62f2dfe89f88","home_score":5,"away_score":1,"forfeit_side":null},{"fixture_id":"8756948b-3fcd-47ff-b570-ce70f0f47946","home_score":10,"away_score":10,"forfeit_side":null},{"fixture_id":"a3e389f2-634f-4215-816e-049fc52e3c95","home_score":5,"away_score":7,"forfeit_side":null},{"fixture_id":"bc0668f2-2fa7-42ce-b1ce-ad18b0a478be","home_score":5,"away_score":2,"forfeit_side":null},{"fixture_id":"48c204ff-64e9-414c-b6c8-17217afbc9f7","home_score":4,"away_score":12,"forfeit_side":null},{"fixture_id":"c553b39f-1113-4db6-b4e2-a2104d963d4e","home_score":9,"away_score":9,"forfeit_side":null}]$scores$::jsonb) r(fixture_id uuid,home_score integer,away_score integer,forfeit_side text);
UPDATE public.seasons SET ends_on='2027-05-31' WHERE id='ba8c0e2f-7f8a-41be-8ddb-65b320cebaa2';
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM roster_plan p LEFT JOIN public.fixtures f ON f.id=p.id WHERE f.id IS NULL OR ROW(f.competition_season_id,f.round_number,f.match_date,f.kickoff_time,f.court,f.home_team_id,f.away_team_id,f.publication_state,f.schedule_status) IS DISTINCT FROM ROW(p.competition_season_id,p.round_number,p.match_date,p.kickoff_time,p.court,p.home_team_id,p.away_team_id,p.publication_state,p.schedule_status)) OR (SELECT count(*) FROM public.fixtures WHERE competition_season_id IN('62ce7ec9-459e-4acf-bec5-c6734a3199ef','be008d39-f175-45c1-a232-2148d84b1cf9'))<>480 THEN RAISE EXCEPTION 'Postflight: exact fixture reconciliation failed'; END IF;
 IF EXISTS(SELECT competition_season_id FROM public.teams WHERE competition_season_id IN('62ce7ec9-459e-4acf-bec5-c6734a3199ef','be008d39-f175-45c1-a232-2148d84b1cf9') AND status='active' AND standings_eligible GROUP BY competition_season_id HAVING count(*)<>16) THEN RAISE EXCEPTION 'Postflight: expected 16 active teams per night'; END IF;
 IF EXISTS(SELECT data FROM protected_roster_rows WHERE kind='fixtures' EXCEPT SELECT to_jsonb(f) FROM public.fixtures f) OR EXISTS(SELECT data FROM protected_roster_rows WHERE kind='results' EXCEPT SELECT to_jsonb(r) FROM public.result_versions r) OR EXISTS(SELECT data FROM protected_roster_rows WHERE kind='adjustments' EXCEPT SELECT to_jsonb(a) FROM public.standing_adjustments a) OR EXISTS(SELECT data FROM protected_roster_rows WHERE kind='audit' EXCEPT SELECT to_jsonb(a) FROM public.admin_audit_log a) OR EXISTS(SELECT data FROM protected_roster_rows WHERE kind='notes' EXCEPT SELECT to_jsonb(n) FROM public.team_fixture_notes n) OR EXISTS(SELECT data FROM protected_roster_rows WHERE kind='preferences' EXCEPT SELECT to_jsonb(v) FROM public.team_kickoff_preferences v) THEN RAISE EXCEPTION 'Protected history changed'; END IF;
 IF (SELECT count(*) FROM public.result_versions r JOIN public.fixtures f ON f.id=r.fixture_id WHERE f.competition_season_id IN('62ce7ec9-459e-4acf-bec5-c6734a3199ef','be008d39-f175-45c1-a232-2148d84b1cf9') AND r.status='published')<>16 THEN RAISE EXCEPTION 'Postflight: expected eight results per night'; END IF;
END $$;
COMMIT;
